scwin.btn_register_onclick = function(e) {
    console.log("결함 등록 버튼 클릭");

    // 현재 사용자 정보 가져오기
    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName();
    var currentProjectId = scwin.CURRENT_PROJECT_ID || "";

    console.log("팝업에 전달할 사용자 정보:");
    console.log("- USER_ID:", currentUserId);
    console.log("- USER_NAME:", currentUserName);
    console.log("- PROJECT_ID:", currentProjectId);

    // UnitTestList.xml과 동일한 방식으로 데이터 준비
    var defectData = {
        mode: "new",
        id: "",
        pjtId: currentProjectId,
        currentUserId: currentUserId,
        currentUserName: currentUserName
    };

    var jsnPopupData = {
        "type": "json",
        "name": "defectData",  // UnitTestList에서는 "taskData"였지만 결함에서는 "defectData"
        "data": defectData
    };

    var options = {
        id: "defect_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "결함 등록",
        modal: true,
        closeAction: "scwin.defectPopup_closeAction",
        dataObject: jsnPopupData  // 이 부분이 중요!
    };

    console.log("팝업 열기 - 사용자 정보 포함:", defectData);
    // 경로 수정: /InsWebApp/ui/def/ -> /InsWebApp/def/
    $p.openPopup("/InsWebApp/def/DefectPopup.xml", options);
};

/**
 * 현재 사용자명 가져오기
 */
scwin.getCurrentUserName = function() {
    try {
        var parentWindow = $p.getParentWindow();
        if (parentWindow) {
            var headerFrame = parentWindow.$p.getComponentById("pg_header");
            if (headerFrame && headerFrame.getWindow && headerFrame.getWindow().scwin) {
                var headerScwin = headerFrame.getWindow().scwin;

                if (headerScwin.USER_NAME) {
                    console.log("헤더에서 사용자 이름 가져옴:", headerScwin.USER_NAME);
                    return headerScwin.USER_NAME;
                }
            }
        }

        console.log("헤더에서 사용자 이름을 가져올 수 없음, 기본값 사용");
        return "사용자";

    } catch (e) {
        console.error("사용자 이름 가져오기 실패:", e);
        return "사용자";
    }
};

/**
 * 결함 팝업 열기 (상세보기용)
 */
scwin.openDefectPopup = function(defectData, mode) {
    console.log("결함 팝업 열기:", mode, defectData);

    if (!defectData || !defectData.id) {
        $c.win.alert("유효하지 않은 데이터입니다.");
        return;
    }

    // 현재 사용자 정보 가져오기
    var currentUserId = scwin.CURRENT_USER_ID || "1";
    var currentUserName = scwin.getCurrentUserName();
    var currentProjectId = scwin.CURRENT_PROJECT_ID || "";

    // 팝업 데이터 준비
    var popupData = {
        mode: mode,
        defectData: defectData,
        pjtId: currentProjectId,
        currentUserId: currentUserId,
        currentUserName: currentUserName
    };

    var jsnPopupData = {
        "type": "json",
        "name": "defectData",
        "data": popupData
    };

    var options = {
        id: "defect_detail_popup",
        type: "wframePopup",
        width: "1400px",
        height: "900px",
        top: "50px",
        left: "100px",
        popupName: "결함 상세정보",
        modal: true,
        closeAction: "scwin.defectPopup_closeAction",
        dataObject: jsnPopupData
    };

    console.log("팝업 열기 - 상세 데이터 포함:", popupData);
    $p.openPopup("/InsWebApp/ui/def/DefectPopup.xml", options);
};

